when CLIENT_ACCEPTED {
  if { [TCP::local_port] == 80 } {
    SSL::disable
    pool myPool
  } elseif { [TCP::local_port] == 443 } {
    pool myPool
  } else {
    discard
  }
}

when HTTP_REQUEST {
  set usessl 0
  if { [string tolower [HTTP::uri]] starts_with "/secure" } {
    pool ssl__pool
    set usessl 1
  } else {
    pool static_pool
    set usessl 0
  }
}
when SERVER_CONNECTED {
  if { $usessl == 0 } {
    SSL::disable
  }
}

when HTTP_REQUEST {
  if { [HTTP::uri] starts_with "/old"}{
    SSL::disable serverside
    pool TestPool1
  } else {
    pool TestPool2
  }
}
